import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = sorted(set(data[1:1 + n]))
    S = set(words)
    maxlen = max(len(w) for w in words)
    out = []
    for w in words:
        L = len(w)
        ok = [False] * (L + 1)
        ok[L] = True
        nxt = [[] for _ in range(L + 1)]
        for i in range(L - 1, -1, -1):
            for j in range(i + 1, min(L, i + maxlen) + 1):
                if i == 0 and j == L:
                    continue
                if ok[j] and w[i:j] in S:
                    nxt[i].append(j)
            ok[i] = bool(nxt[i])
        if not ok[0]:
            continue
        parts = []

        def dfs(i):
            if i == L:
                out.append(w + ': ' + ' '.join(parts))
                return
            for j in nxt[i]:
                parts.append(w[i:j])
                dfs(j)
                parts.pop()

        dfs(0)
    print(len(out))
    for line in out:
        print(line)

