def gen(rng):
    def fmt(ws):
        return str(len(ws)) + "\n" + " ".join(ws)

    def total_splits(ws):
        S = set(ws)
        tot = 0
        for w in S:
            L = len(w)
            cnt = [0] * (L + 1)
            cnt[L] = 1
            for i in range(L - 1, -1, -1):
                c = 0
                for j in range(i + 1, L + 1):
                    if i == 0 and j == L:
                        continue
                    if cnt[j] and w[i:j] in S:
                        c += cnt[j]
                cnt[i] = c
            tot += cnt[0]
        return tot

    tests = [
        fmt(["a"]), fmt(["a", "a"]), fmt(["a", "aa"]), fmt(["ab", "cd", "abcd"]), fmt(["abcd", "cd", "ab", "abcdab", "ab"]),
        fmt(["a", "aa", "aaa", "aaaa", "aaaaa", "aaaaaa"]),
        fmt(["x", "y", "z"]),
        fmt("happy rise for set sunrise sun su nset sunset mind happymind n rise happysunrise".split()),
        fmt(["ab", "b", "a", "abab", "bab", "aba"]),
    ]
    for n in (2, 3, 4, 5, 6, 8, 10):
        for alpha in ("ab", "abc"):
            for _ in range(2):
                ws = []
                for _ in range(n):
                    L = rng.randint(1, 4)
                    ws.append("".join(rng.choice(alpha) for _ in range(L)))
                tests.append(fmt(ws))
    # powers of a: many splits
    tests.append(fmt(["a" * k for k in range(1, 15)]))
    # small alphabet, many ambiguous splits (kept under the limit)
    ws = ["".join(rng.choice("ab") for _ in range(rng.randint(1, 3))) for _ in range(12)]
    ws += ["".join(rng.choice("ab") for _ in range(rng.randint(8, 13))) for _ in range(40)]
    while total_splits(ws) > 30000:
        ws.pop()
    tests.append(fmt(ws))
    # large: base vocabulary plus composites, with duplicates allowed
    def big(alpha, nbase, lo, hi, n, maxparts):
        base = []
        seen = set()
        while len(base) < nbase:
            w = "".join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
            if w not in seen:
                seen.add(w)
                base.append(w)
        ws = list(base)
        while len(ws) < n:
            k = rng.randint(2, maxparts)
            w = "".join(rng.choice(base) for _ in range(k))
            if len(w) <= 30:
                ws.append(w)
        rng.shuffle(ws)
        return ws

    for args in (("abcdefghijklmnopqrstuvwxyz", 300, 2, 4, 3000, 8), ("abcdefgh", 400, 2, 5, 3000, 7), ("abcd", 150, 3, 6, 3000, 6)):
        ws = big(*args)
        while total_splits(ws) > 30000:
            ws = ws[: int(len(ws) * 0.9)]
        tests.append(fmt(ws))
    w30 = ["abcde" * 6, "abcde", "abc", "de", "abcdeabcde", "abcdeabcdeabcde", "a", "bcde", "abcdeabc"]
    tests.append(fmt(w30))
    return tests

